import{_ as o,C as a,o as c,c as r,a5 as t,E as n}from"./chunks/framework.-jms6n7v.js";const u=JSON.parse('{"title":"Types","description":"The types the API takes and returns, each on a page of its own, listed here for the language chosen in the sidebar.","frontmatter":{"title":"Types","order":1,"pageClass":"reference-page","prev":{"text":"API","link":"/api/"},"next":{"text":"Comparison","link":"/compare"}},"headers":[{"level":2,"title":"Field types in every language","slug":"field-types-in-every-language","link":"#field-types-in-every-language","children":[]}],"relativePath":"types/index.md","filePath":"en/types/index.md","lastUpdated":1791607547000}'),i={name:"types/index.md"};function s(l,e,p,h,y,g){const d=a("PageList");return c(),r("div",null,[e[0]||(e[0]=t('<h1 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h1><p>The types the API takes and returns, each on a page of its own, listed here for the language chosen in the sidebar.</p><div class="lang-only" data-code-lang="rust"><p>Every type is exported from the crate&#39;s root, as <code>darudb::Value</code>. The calls that take and return them are in <a href="./../api/">API</a>.</p></div><div class="lang-only" data-code-lang="node"><p>The types are exported from the package&#39;s root for TypeScript: <code>import type { OpenOptions } from &#39;darudb&#39;;</code>. The calls that take and return them are in <a href="./../api/">API</a>.</p></div><div class="lang-only" data-code-lang="dart"><p>The types are exported from the package&#39;s library, <code>package:darudb/darudb.dart</code>. The calls that take and return them are in <a href="./../api/">API</a>.</p></div><div class="lang-only" data-code-lang="python"><p>The types are exported from the package&#39;s root, as <code>darudb.Key</code> or <code>from darudb import CheckReport</code>, and the package ships type hints for them. The calls that take and return them are in <a href="./../api/">API</a>.</p></div>',6)),n(d,{section:"types",grouped:""}),e[1]||(e[1]=t('<h2 id="field-types-in-every-language" tabindex="-1">Field types in every language <a class="header-anchor" href="#field-types-in-every-language" aria-label="Permalink to &quot;Field types in every language&quot;">​</a></h2><p>A field of a schema holds one of these. Each package declares it in its own way and reads it as one of its own types, and a file written from one language reads the same from the others.</p><table tabindex="0"><thead><tr><th>A field that holds</th><th>Rust</th><th>Node.js</th><th>Dart</th><th>Python</th></tr></thead><tbody><tr><td>A boolean</td><td><code>Type::Bool</code>, <code>bool</code></td><td><code>t.bool()</code>, <code>boolean</code></td><td><code>bool</code></td><td><code>bool</code></td></tr><tr><td>A 64-bit integer</td><td><code>Type::Int</code>, <code>i64</code></td><td><code>t.int()</code>, <code>number</code>, or <code>t.bigint()</code>, <code>bigint</code></td><td><code>int</code></td><td><code>int</code></td></tr><tr><td>A 64-bit float</td><td><code>Type::Float</code>, <code>f64</code></td><td><code>t.float()</code>, <code>number</code></td><td><code>double</code></td><td><code>float</code></td></tr><tr><td>Text</td><td><code>Type::String</code>, <code>String</code></td><td><code>t.string()</code>, <code>string</code></td><td><code>String</code></td><td><code>str</code></td></tr><tr><td>Bytes</td><td><code>Type::Bytes</code>, <code>Vec&lt;u8&gt;</code></td><td><code>t.bytes()</code>, <code>Uint8Array</code></td><td><code>Uint8List</code></td><td><code>bytes</code></td></tr><tr><td>A list</td><td><code>Type::list(...)</code>, <code>Vec&lt;T&gt;</code></td><td><code>t.list(...)</code>, an array</td><td><code>List&lt;E&gt;</code></td><td><code>list[E]</code></td></tr><tr><td>A link to another collection</td><td><code>Type::link(...)</code>, <code>Link&lt;T&gt;</code></td><td><code>t.link(...)</code>, the key</td><td><code>Link&lt;T&gt;</code></td><td>the key type, with <code>field(link=...)</code></td></tr><tr><td>An embedded object</td><td><code>Type::object(...)</code>, a struct with <code>#[derive(Embedded)]</code></td><td><code>t.object({...})</code>, an object</td><td>an <code>@Embedded()</code> class</td><td>an <code>@darudb.embedded</code> class</td></tr><tr><td>Nothing, when optional</td><td><code>optional(...)</code>, <code>Option&lt;T&gt;</code></td><td><code>.optional()</code>, <code>null</code></td><td>a nullable type, <code>null</code></td><td><code>X | None</code>, <code>None</code></td></tr></tbody></table><p>In Rust, the first of each pair declares the field in a <a href="./../api/rust/schema"><code>Schema</code></a> and the second is its type in a struct that <a href="./../api/rust/derive"><code>#[derive(Object)]</code></a> makes a collection. In Node.js, the first is the <a href="./../api/node/t"><code>t</code></a> builder and the second what an object holds. Dart and Python declare a field by its type in a class. The field types page of each language has the details.</p>',4))])}const b=o(i,[["render",s]]);export{u as __pageData,b as default};
